import os
def transform(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    # find connected 5 components
    seen=set()
    for i in range(h):
        for j in range(w):
            if g[i][j]==5 and (i,j) not in seen:
                comp=[(i,j)]; seen.add((i,j)); q=[(i,j)]
                while q:
                    y,x=q.pop()
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if 0<=a<h and 0<=b<w and g[a][b]==5 and (a,b) not in seen:
                            seen.add((a,b)); comp.append((a,b)); q.append((a,b))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                # interior: zeros enclosed (not reachable from border through zeros within bbox... use flood from outside)
                # flood zeros of whole grid outside shape
                interior=[]
                # flood fill from border over zeros and shape? simpler: cell is interior if zero and all paths to border cross shape.
                # do flood from border over zeros, treating 5 as wall
                from collections import deque
                outside=set(); dq=deque()
                for a in range(h):
                    for b in (0,w-1):
                        if g[a][b]==0: dq.append((a,b)); outside.add((a,b))
                for b in range(w):
                    for a in (0,h-1):
                        if g[a][b]==0: dq.append((a,b)); outside.add((a,b))
                while dq:
                    y,x=dq.popleft()
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if 0<=a<h and 0<=b<w and g[a][b]==0 and (a,b) not in outside:
                            outside.add((a,b)); dq.append((a,b))
                for a in range(r0,r1+1):
                    for b in range(c0,c1+1):
                        if g[a][b]==0 and (a,b) not in outside:
                            out[a][b]=2; interior.append((a,b))
                # gap: zero in top row of bbox within [c0,c1]
                top=r0
                gaps=[b for b in range(c0,c1+1) if g[top][b]==0]
                if gaps:
                    gap=gaps[0]
                    out[top][gap]=2
                    # spill direction: longer run of 5s in top row
                    left=sum(1 for b in range(c0,gap) if g[top][b]==5)
                    right=sum(1 for b in range(gap+1,c1+1) if g[top][b]==5)
                    d=-1 if left>=right else 1
                    b=gap+d
                    while 0<=b<w:
                        out[top][b]=2; b+=d
    return out

